  },
  "plan": {
    "schemaVersion": "gray-plan-3",
    "deckBrief": {
      "title": "图书馆服务复盘",
      "audience": "馆务会议",
      "objective": "说明本月读者服务、馆藏维护与内部协作的情况"
    },
    "pages": [
      {
        "pageId": "p1",
        "title": "读者服务三项发现",
        "claim": "预约提示不清、咨询口径已统一、夜间仍无固定承接人",
        "pagePurpose": "汇总本月读者服务的三项发现",
        "narrative": "三项发现并列：预约取书提示问题、咨询台口径统一、夜间咨询承接缺口；每项各自带出对应后果或状态。",
        "groups": [
          {
            "id": "g1",
            "role": "并列说明读者服务三项发现及其后果",
            "importance": "primary",
            "heading": "读者服务三项发现",
            "kind": "text",
            "blocks": [
              {
                "id": "b1",
                "label": "预约取书提示不清",
                "text": "读者常把到馆通知理解为已完成借阅。",
                "sourceIds": [
                  "s1"
                ]
              },
              {
                "id": "b2",
                "label": "咨询台",
                "text": "已统一回答口径。",
                "sourceIds": [
                  "s1"
                ]
              },
              {
                "id": "b3",
                "label": "夜间咨询",
                "text": "尚无固定承接人；遇到跨部门问题只能留单，第二天再转交。",
                "sourceIds": [
                  "s1"
                ]
              }
            ]
          }
        ],
        "planningNotes": "三项发现同属读者服务，作为并列条目展开，保留各自后果与限制条件。"
      },
      {
        "pageId": "p2",
        "title": "馆藏维护两项进展",
        "claim": "已完成破损书目登记，修复仍需按损坏程度排队",
        "pagePurpose": "说明馆藏维护的进展与未完成条件",
        "narrative": "登记已完成，修复受损坏程度排队约束，两者是不同进度，不可等同。",
        "groups": [
          {
            "id": "g2",
            "role": "说明馆藏维护的进展与未完成部分",
            "importance": "primary",
            "heading": "馆藏维护两项进展",
            "kind": "text",
            "blocks": [
              {
                "id": "b4",
                "label": "已完成",
                "text": "破损书目登记。",
                "sourceIds": [
                  "s1"
                ]
              },
              {
                "id": "b5",
                "label": "仍需排队",
                "text": "修复工作按损坏程度排队；登记完成不等于修复完成。",
                "sourceIds": [
                  "s1"
                ]
              }
            ]
          }
        ],
        "planningNotes": "两项进展有先后与否定关系，需保留‘不等于’的限定。"
      },
      {
        "pageId": "p3",
        "title": "内部协作安排",
        "claim": "每周集中核对未结工单，由原接单人员跟踪至接收部门确认",
        "pagePurpose": "说明内部协作的一项安排",
        "narrative": "按接收部门确认结果作为跟踪终点。",
        "groups": [
          {
            "id": "g3",
            "role": "说明内部协作安排的执行方式与终点",
            "importance": "primary",
            "heading": "内部协作安排",
            "kind": "text",
            "blocks": [
              {
                "id": "b6",
                "text": "每周集中核对未结工单，由原接单人员持续跟踪，直到接收部门确认处理结果。",
                "sourceIds": [
                  "s1"
                ]
              }
            ]
          }
        ],
        "planningNotes": "仅一项安排，独立成页，明确责任人、频次和跟踪终点。"
      }
    ],
    "planningNotes": "原稿为模拟稿件，面向馆务会议，分为读者服务、馆藏维护、内部协作三块；模拟声明在主题或正文中出现一次即可。"
  }
}
